#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-check-an-app-uploaded-the-right-file. Do not edit.
set -e
cd "$(dirname "$0")"
cat > expected.csv <<'EOF'
id,region,total
1,north,42
2,south,17
EOF
cat > app.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# app.sh FTP-URL [broken]: the app under test. It writes tonight's export, nightly.csv, and uploads it to
# exports/nightly.csv under the FTP URL (ending in /), making the folder if need be. Given broken, it leaves out
# the last row, as a bug would. A failed upload is curl's exit code.
rows='1,north,42
2,south,17'
if [ "$2" = broken ]; then rows='1,north,42'; fi
printf 'id,region,total\n%s\n' "$rows" > nightly.csv
curl -sS --ftp-create-dirs -T nightly.csv "${1}exports/nightly.csv"
EOF
cat > check.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# check.sh FILE-URL EXPECTED: fetches the uploaded file over HTTP into arrived.csv and compares it, byte for
# byte, with EXPECTED. Exit 1 when they differ; a failed fetch (a 404 included, through -f) is curl's exit code.
curl -sS -f -o arrived.csv "$1" || exit
if cmp -s "$2" arrived.csv; then echo "matches $2"; exit 0; fi
echo "differs from $2: expected $(wc -c < "$2" | tr -d ' ') bytes, arrived $(wc -c < arrived.csv | tr -d ' ')"
exit 1
EOF
surl --allow-anonymous --allow-uploads ftp://127.0.0.1:8080/ http://127.0.0.1:8081/ &
sleep 1
sh app.sh ftp://127.0.0.1:8080/ && sh check.sh http://127.0.0.1:8081/exports/nightly.csv expected.csv
kill $(jobs -p)
